def is_valid_vpa(s):
    # Check if string length is between 2 and 256
    if not 2 <= len(s) <= 256:
        return False

    # Check if the string contains only allowed characters
    if not re.match(r'^[a-zA-Z0-9.\-\_]+@[a-zA-Z0-9.-_]+$', s):
        return False

    # Check if the part after '@' is a provider name (2-64 characters)
    provider_name = s.split('@')[1]
    if not 2 <= len(provider_name) <= 64 or not provider_name.isalpha():
        return False

    return True

